// Entrada: { doc_id, flow? }. El nombre del flujo elige las etiquetas (flujo:<flow>[:estado]) y la hoja destino
// (FLOWS_SHEETS_TARGETS = {"sheets": {"id": "...", "tab": "Facturas"}, "sheets-luis": {...}}).
const flow = String($json.flow || 'sheets');
if (!/^[a-z0-9-]+$/.test(flow)) throw new Error(`Nombre de flujo inválido: ${flow}`);
let targets = {};
try { targets = JSON.parse($env.FLOWS_SHEETS_TARGETS || '{}'); } catch (e) { throw new Error('FLOWS_SHEETS_TARGETS no es JSON válido'); }
const sheet = targets[flow] || { id: '', tab: 'Facturas' };
const prefix = `flujo:${flow}`;
return [{ json: { doc_id: Number($json.doc_id), flow, prefix, sheet: { id: sheet.id || '', tab: sheet.tab || 'Facturas' } } }];

// La etiqueta "procesando" está en has_not_tags del workflow nativo: las escrituras que siguen no lo vuelven a disparar.
const c = $('Config').first().json;
return [{ json: { doc_id: $json.id, add_tags: [`${c.prefix}:procesando`] } }];

// Recupera el documento y su archivo (la llamada anterior devolvió solo un resumen) y arma el formulario para Formularios.
const d = $('Leer documento').first();
const form = "{\"title\": \"Factura\", \"fields\": [{\"key\": \"ruc_emisor\", \"role\": \"ruc_emisor\"}, {\"key\": \"numero_factura\", \"role\": \"numero_factura\"}, {\"key\": \"fecha_emision\", \"role\": \"fecha_emision\"}, {\"key\": \"subtotal\", \"role\": \"subtotal\"}, {\"key\": \"iva\", \"role\": \"iva\"}, {\"key\": \"total\", \"role\": \"total\"}]}";
return [{ json: { id: d.json.id, title: d.json.title, form }, binary: d.binary }];

// Convierte la respuesta de Formularios en campos de Paperless, una fila para Sheets y el estado (ok / revisar).
const doc = $('Leer documento').first().json;
const cfg = $('Config').first().json;
const res = $input.first().json;
if (res.error || !Array.isArray(res.fields)) {
  let err = res.error ? (typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error))) : 'respuesta sin campos';
  err = err.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);
  return [{ json: { ok: false, doc_id: doc.id, error: err } }];
}
const byKey = Object.fromEntries(res.fields.map(f => [f.key, f]));
const val = k => (byKey[k] && byKey[k].value != null && byKey[k].value !== '') ? byKey[k].value : null;
const names = { ruc_emisor: 'RUC emisor', numero_factura: 'Número de factura', fecha_emision: 'Fecha de emisión',
  subtotal: 'Subtotal', iva: 'IVA', total: 'Total' };
const fields = {};
for (const [k, n] of Object.entries(names)) fields[n] = val(k);
const clave = res.checks && res.checks.clave_acceso;
if (clave && clave.value) fields['Clave de acceso'] = clave.value;
const dudosos = res.fields.filter(f => f.status !== 'green').map(f => `${f.label}${f.value ? ' = ' + f.value : ' (vacío)'}`);
const totals = res.checks && res.checks.totals ? res.checks.totals : {};
const estado = (dudosos.length === 0 && totals.ok !== false) ? 'ok' : 'revisar';
const row = { 'Documento': doc.id, 'Título': doc.title, 'RUC emisor': val('ruc_emisor'),
  'Número de factura': val('numero_factura'), 'Fecha de emisión': val('fecha_emision'),
  'Subtotal': val('subtotal'), 'IVA': val('iva'), 'Total': val('total'), 'Estado': estado,
  'Enlace': `${$env.PAPERLESS_PUBLIC_URL}/documents/${doc.id}/details`, 'Procesado': new Date().toISOString() };
return [{ json: { ok: true, doc_id: doc.id, flow: cfg.flow, sheet: cfg.sheet, estado, fields, dudosos, totals_note: totals.ok === false ? totals.note : null, row } }];

// Decide la etiqueta final y redacta la nota que queda en el documento.
const r = $('Interpretar').first().json;
const cfg = $('Config').first().json;
const sheetsRan = $('Agregar fila').isExecuted;
const sheetsOut = sheetsRan ? $('Agregar fila').first().json : null;
const sheetsErr = sheetsOut && sheetsOut.error ? (typeof sheetsOut.error === 'string' ? sheetsOut.error : (sheetsOut.error.message || JSON.stringify(sheetsOut.error))) : null;
const lines = [];
let estado;
if (!r.ok) {
  estado = 'error';
  lines.push(`Formularios no pudo leer el documento: ${r.error}`);
} else {
  estado = r.estado;
  if (r.dudosos.length) lines.push('Campos por revisar: ' + r.dudosos.join('; '));
  if (r.totals_note) lines.push(r.totals_note);
  if (sheetsRan && !sheetsErr) lines.push(`Fila agregada en Google Sheets (${cfg.sheet.tab}).`);
  if (sheetsErr) { estado = 'error'; lines.push(`No se pudo escribir en Google Sheets: ${sheetsErr}`); }
  if (!cfg.sheet.id) lines.push(`Google Sheets no configurado para el flujo ${cfg.flow} (FLOWS_SHEETS_TARGETS).`);
}
const labels = { ok: 'lectura completa', revisar: 'lectura con dudas', error: 'error' };
return [{ json: { doc_id: r.doc_id, add_tags: [`${cfg.prefix}:${estado}`], remove_tags: [`${cfg.prefix}:procesando`],
  fields: r.ok ? r.fields : {}, note: `Flujo ${cfg.flow}: ${labels[estado]}.` + (lines.length ? '\n' + lines.join('\n') : '') } }];
